import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;
import java.util.ArrayList;
import java.util.List;

public final class ClaimOfficeCli {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private ClaimOfficeCli() {
    }

    public static int run(InputStream in, PrintStream out, PrintStream err) {
        JsonNode scenario;
        try {
            scenario = MAPPER.readTree(in);
        } catch (IOException e) {
            err.println(e.getMessage());
            return 1;
        }
        Customer customer = ScenarioJson.customerOf(scenario);
        List<String> results = new ArrayList<>();
        int precedingContracts = 0;
        for (JsonNode step : ScenarioJson.stepsOf(scenario)) {
            List<Item> items = ScenarioJson.itemsOf(step);
            results.add(ScenarioJson.quoteResult(
                    PremiumCalculator.premiumFor(customer, precedingContracts, items)));
            precedingContracts++;
        }
        out.print(ScenarioJson.results(results));
        return 0;
    }

    public static void main(String[] args) {
        System.exit(run(System.in, System.out, System.err));
    }
}
