import java.math.BigDecimal;

/**
 * The policy-wide modifiers the MHPCO applies to a policy base premium.
 *
 * <p>Unlike the item-specific risk surcharges, these follow from the customer's
 * standing with the MHPCO rather than from any insured item, and they are
 * measured against the policy base premium, the sum of all item base premiums.
 *
 * <p>Returns a signed amount: what the customer's standing adds to the policy
 * base premium. A discount is therefore negative.
 *
 * <p>Changes whenever the MHPCO revises a modifier's rate or the condition
 * under which it is applied.
 */
final class PolicyModifiers {

    private static final int LOYALTY_DISCOUNT_PERCENT = 20;
    private static final int LOYALTY_FROM_YEARS = 2;
    private static final int FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
    private static final int FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;

    private PolicyModifiers() {
    }

    static BigDecimal of(Customer customer, int precedingContracts, BigDecimal policyBasePremium) {
        return firstInsuranceSurcharge(policyBasePremium)
                .subtract(loyaltyDiscount(customer, policyBasePremium))
                .subtract(followUpContractDiscount(precedingContracts, policyBasePremium));
    }

    /**
     * Every contract after the customer's first is a follow-up contract.
     */
    private static BigDecimal followUpContractDiscount(int precedingContracts,
            BigDecimal policyBasePremium) {
        if (precedingContracts == 0) {
            return BigDecimal.ZERO;
        }
        return Percentage.of(FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT).ofAmount(policyBasePremium);
    }

    /**
     * Every quote is an initial assessment: each item of a quote is treated as
     * a first insurance, whatever the customer's history.
     */
    private static BigDecimal firstInsuranceSurcharge(BigDecimal policyBasePremium) {
        return Percentage.of(FIRST_INSURANCE_SURCHARGE_PERCENT).ofAmount(policyBasePremium);
    }

    private static BigDecimal loyaltyDiscount(Customer customer, BigDecimal policyBasePremium) {
        if (!isLongStanding(customer)) {
            return BigDecimal.ZERO;
        }
        return Percentage.of(LOYALTY_DISCOUNT_PERCENT).ofAmount(policyBasePremium);
    }

    /**
     * The MHPCO reads "long-standing" inclusively: a customer at exactly the
     * threshold already qualifies.
     */
    private static boolean isLongStanding(Customer customer) {
        return customer.yearsWithMHPCO() >= LOYALTY_FROM_YEARS;
    }
}
