import java.math.BigDecimal;
import java.util.Map;
import java.util.Set;

/**
 * The MHPCO price list: the base premium each kind of item is tariffed at.
 *
 * <p>The MHPCO tariffs main items individually and components as a category:
 * every component carries the same base premium, whatever it is made of.
 *
 * <p>Changes whenever the MHPCO revises its tariff or takes on a new kind of
 * item; knows nothing about how a premium is assembled from those amounts.
 */
final class PriceList {

    private static final int SWORD_BASE_PREMIUM_IN_G = 100;
    private static final int AMULET_BASE_PREMIUM_IN_G = 60;
    private static final int STAFF_BASE_PREMIUM_IN_G = 80;
    private static final int POTION_BASE_PREMIUM_IN_G = 40;

    private static final int COMPONENT_BASE_PREMIUM_IN_G = 25;

    private static final int NOT_TARIFFED = 0;

    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUMS_IN_G = Map.of(
            "sword", SWORD_BASE_PREMIUM_IN_G,
            "amulet", AMULET_BASE_PREMIUM_IN_G,
            "staff", STAFF_BASE_PREMIUM_IN_G,
            "potion", POTION_BASE_PREMIUM_IN_G);

    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");

    private PriceList() {
    }

    static BigDecimal basePremiumFor(Item item) {
        if (isComponent(item)) {
            return BigDecimal.valueOf(COMPONENT_BASE_PREMIUM_IN_G);
        }
        return BigDecimal.valueOf(MAIN_ITEM_BASE_PREMIUMS_IN_G.getOrDefault(item.type(), NOT_TARIFFED));
    }

    private static boolean isComponent(Item item) {
        return COMPONENT_TYPES.contains(item.type());
    }
}
