import java.util.ArrayList;
import java.util.List;

/**
 * A customer's dealings with the MHPCO, worked through in order.
 *
 * <p>Holds the MHPCO's reading of how one step bears on the next: the steps of
 * a scenario are settled sequentially for a single customer, and every contract
 * concluded before a step makes that step a follow-up contract. Defers what a
 * step costs to the premium calculation, and knows nothing about the wire
 * format a scenario arrived in or its results are written back in.
 *
 * <p>Changes whenever the MHPCO revises what an earlier step counts for when a
 * later one is settled.
 */
final class Scenario {

    private final Customer customer;
    private final List<List<Item>> quotedItems;

    Scenario(Customer customer, List<List<Item>> quotedItems) {
        this.customer = customer;
        this.quotedItems = List.copyOf(quotedItems);
    }

    /**
     * The premium of every step, in the order the MHPCO worked through them.
     */
    List<Integer> premiums() {
        List<Integer> premiums = new ArrayList<>();
        for (List<Item> items : quotedItems) {
            premiums.add(PremiumCalculator.premiumFor(customer, premiums.size(), items));
        }
        return premiums;
    }
}
