import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;

public final class ClaimOfficeCli {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private ClaimOfficeCli() {
    }

    public static int run(InputStream in, PrintStream out, PrintStream err) {
        JsonNode scenario;
        try {
            scenario = MAPPER.readTree(in);
        } catch (IOException e) {
            err.println(e.getMessage());
            return 1;
        }
        out.print(ScenarioJson.results(ScenarioJson.scenarioOf(scenario).premiums()));
        return 0;
    }

    public static void main(String[] args) {
        System.exit(run(System.in, System.out, System.err));
    }
}
import com.fasterxml.jackson.databind.JsonNode;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Translates between the MHPCO wire format and the domain.
 *
 * <p>Changes whenever the JSON schema of a scenario or of a results document
 * changes; knows nothing about tariffs, premiums or the command line.
 */
final class ScenarioJson {

    private ScenarioJson() {
    }

    static Scenario scenarioOf(JsonNode scenario) {
        List<List<Item>> quotedItems = new ArrayList<>();
        for (JsonNode step : scenario.get("steps")) {
            quotedItems.add(itemsOf(step));
        }
        return new Scenario(customerOf(scenario), quotedItems);
    }

    private static List<Item> itemsOf(JsonNode quoteStep) {
        List<Item> items = new ArrayList<>();
        for (JsonNode item : quoteStep.get("items")) {
            items.add(new Item(item.get("type").asText(), item.path("enchantment").asInt(),
                    item.path("cursed").asBoolean()));
        }
        return items;
    }

    private static Customer customerOf(JsonNode scenario) {
        return new Customer(scenario.get("customer").get("yearsWithMHPCO").asInt());
    }

    static String results(List<Integer> premiums) {
        return "{\"results\":[" + premiums.stream()
                .map(ScenarioJson::quoteResult)
                .collect(Collectors.joining(",")) + "]}";
    }

    private static String quoteResult(int premium) {
        return "{\"premium\":" + premium + "}";
    }
}

